package platform.contentapi.management;

import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import platform.contentapi.execution.*;
import tools.jackson.databind.JsonNode;
import static org.assertj.core.api.Assertions.*;
import static platform.contentapi.management.SourceFixtures.*;

/** Real SeaweedFS through a signed-request-preserving fault proxy, real PostgreSQL, actual Java child. */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class RssBronzeIT extends RssFetchFixtures {
    BronzeFaultProxy proxy;Path credentials,journalDirectory;String bronzeRuntime="bronze-test";RssFetchTestSupport.Observed fetched;
    @BeforeAll void awaitRealBucket()throws Exception {manifest=RssFetchTestSupport.manifest();long end=System.nanoTime()+java.time.Duration.ofSeconds(20).toNanos();AssertionError last=null;do{try{assertThat(fixture("head")).isEqualTo("READY");return;}catch(AssertionError ex){last=ex;Thread.sleep(200);}}while(System.nanoTime()<end);throw last;}
    @BeforeEach @Override void setup(){try{
        bronzeRuntime="bronze-test";journalDirectory=null;fetched=null;
        proxy=new BronzeFaultProxy(Objects.requireNonNull(System.getenv("BRONZE_S3_ENDPOINT")));
        credentials=Files.createTempFile(temp,"d2-credentials-",".json").toRealPath();Files.setPosixFilePermissions(credentials,PosixFilePermissions.fromString("rw-------"));
        Files.write(credentials,SourceJson.canonical(SourceJson.object().put("accessKey",System.getenv("BRONZE_S3_ACCESS_KEY")).put("secretKey",System.getenv("BRONZE_S3_SECRET_KEY"))));
        super.setup();
    }catch(Exception ex){throw new IllegalStateException(ex);}}
    @AfterEach void closeProxy(){if(proxy!=null)proxy.close();}
    @Override void storage(String id,String product,String role){if(!role.equals("BRONZE")){super.storage(id,product,role);return;}
        byte[] raw=SourceJson.canonical(SourceJson.object().put("importBronzeVersion",1).put("endpoint",proxy.endpoint()).put("region",System.getenv("BRONZE_S3_REGION")).put("bucket",System.getenv("BRONZE_S3_BUCKET")).put("credentialsFile",credentials.toString()));
        jdbc.update("INSERT INTO ddip_management.storage_bindings(binding_id,product,role,configuration_bytes,configuration_sha256,installation_id) VALUES (?,?,?,?,?,?)",id,product,role,raw,SourceJson.sha(raw),INSTALL);
    }
    void prepare(){ready();fetched=fetch();owner=fetched.stage().owner();journalDirectory=directory(fetched.stage());
        var c=SourceJson.object().put("bronzeRuntimeVersion",1).put("adapter","platform.ingestion.managed.ManagedBronze").put("fetchRuntimeId",runtime).put("fetchRuntimeSha256",digest(runtime)).put("runProfileId",CONTENT_PROFILE).put("runProfileSha256",digest(CONTENT_PROFILE)).put("deploymentSha256",SourceJson.sha(SourceJson.canonical(manifest))).put("controlBindingId",guard.binding().id()).put("storageBindingId",BRONZE).put("storageBindingSha256",jdbc.queryForObject("SELECT configuration_sha256 FROM ddip_management.storage_bindings WHERE binding_id=?",String.class,BRONZE));
        byte[] raw=SourceJson.canonical(c);jdbc.update("INSERT INTO ddip_management.execution_profiles(profile_id,configuration_bytes,configuration_sha256) VALUES (?,?,?)",bronzeRuntime,raw,SourceJson.sha(raw));for(String id:List.of(BRONZE,guard.binding().id()))jdbc.update("INSERT INTO ddip_management.execution_profile_storage VALUES (?,?)",bronzeRuntime,id);
    }
    String digest(String id){return jdbc.queryForObject("SELECT configuration_sha256 FROM ddip_management.execution_profiles WHERE profile_id=?",String.class,id);}
    RssBronzeTestSupport.Stored store(){return store((p,o)->{});}
    RssBronzeTestSupport.Stored store(java.util.function.BiConsumer<String,WorkerRepository.Owner> fault){return RssBronzeTestSupport.store(jdbc,tx,workers,guard,owner,bronzeRuntime,fault);}
    RssBronzeTestSupport.Inspection inspectBronze(){return RssBronzeTestSupport.inspect(jdbc,tx,workers,guard,owner.runId(),bronzeRuntime);}
    String fixture(String mode,String... extra)throws Exception {String cp=Path.of("../../ingestion/target/test-classes").toRealPath().toString()+java.io.File.pathSeparator+String.join(java.io.File.pathSeparator,java.util.stream.StreamSupport.stream(manifest.get("classpath").spliterator(),false).map(n->n.get("path").stringValue()).toList());var command=new ArrayList<>(List.of(Path.of(System.getProperty("java.home"),"bin/java").toString(),"-cp",cp,"platform.ingestion.managed.BronzeFixture",mode));if(journalDirectory!=null)command.add(journalDirectory.toString());command.addAll(List.of(extra));var p=new ProcessBuilder(command).redirectError(ProcessBuilder.Redirect.DISCARD).start();String output=p.inputReader().readLine();assertThat(p.waitFor(40,java.util.concurrent.TimeUnit.SECONDS)).isTrue();assertThat(p.exitValue()).as("real SeaweedFS fixture "+mode).isZero();return output;}
    JsonNode snapshot()throws Exception{return SourceJson.parse(fixture("snapshot").getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    Map<String,String> journalSnapshot()throws Exception {var out=new TreeMap<String,String>();try(var files=Files.list(journalDirectory)){for(Path file:files.toList())out.put(file.getFileName().toString(),SourceJson.sha(Files.readAllBytes(file))+":"+Files.getLastModifiedTime(file)+":"+Files.getAttribute(file,"unix:ino"));}return out;}
    void noPrematureSuccess(){assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.rss_deliveries",String.class)).isEqualTo("BRONZE_WRITING");assertThat(jdbc.queryForObject("SELECT receipt_bytes IS NULL FROM ddip_management.rss_deliveries",Boolean.class)).isTrue();assertThat(jdbc.queryForObject("SELECT active_attempt_id FROM ddip_management.coordinator",UUID.class)).isEqualTo(owner.attemptId());assertThat(count("stage_artifacts")).isZero();assertThat(requests.get()).isEqualTo(1);}
    <T> T checked(String phase,java.util.concurrent.Callable<T> action)throws Exception {try{return action.call();}catch(RuntimeException ex){throw new AssertionError(phase+" puts="+proxy.puts.get()+" stages="+jdbc.queryForList("SELECT stage,state FROM ddip_management.stage_invocations")+" backend="+(journalDirectory==null?"not fetched":snapshot()),ex);}}
    @Test void publishesExactOriginalBytesAndReadOnlyReplay()throws Exception {checked("D1 prepare",()->{prepare();return true;});var before=journalSnapshot();var nativeBefore=nativeSnapshot();var stored=checked("STORE_BRONZE",this::store);owner=stored.owner();var receipt=SourceJson.parse(stored.receipt());var actual=snapshot();
        assertThat(Base64.getDecoder().decode(actual.get("payload").get("base64").stringValue())).isEqualTo(payload);assertThat(Base64.getDecoder().decode(actual.get("metadata").get("base64").stringValue())).isEqualTo(Files.readAllBytes(journalDirectory.resolve("metadata.json")));
        assertThat(actual.get("payload").get("contentType").stringValue()).isEqualTo("application/xml");assertThat(actual.get("metadata").get("contentType").stringValue()).isEqualTo("application/json");
        assertThat(jdbc.queryForObject("SELECT receipt_bytes FROM ddip_management.rss_deliveries",byte[].class)).isEqualTo(stored.receipt());assertThat(jdbc.queryForObject("SELECT metadata_sha256 FROM ddip_management.rss_deliveries",String.class)).isEqualTo(SourceJson.sha(Files.readAllBytes(journalDirectory.resolve("metadata.json"))));
        assertThat(receipt.get("ingestionId")).isEqualTo(SourceJson.parse(fetched.descriptor()).get("ingestionId"));assertThat(receipt.get("ingestedAt")).isEqualTo(SourceJson.parse(fetched.descriptor()).get("ingestedAt"));assertThat(proxy.puts.get()).isEqualTo(2);assertThat(proxy.gets.get()).isGreaterThanOrEqualTo(8);
        assertThat(checked("first inspection",this::inspectBronze).receiptConfirmed()).isTrue();assertThat(checked("second inspection",this::inspectBronze).receiptConfirmed()).isTrue();assertThat(proxy.puts.get()).isEqualTo(2);assertThat(snapshot()).isEqualTo(actual);assertThat(journalSnapshot()).isEqualTo(before);assertThat(nativeSnapshot()).isEqualTo(nativeBefore);assertThat(committed()).isTrue();assertThat(requests.get()).isEqualTo(1);assertThat(proxy.deletes.get()).isZero();
        assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.runs",String.class)).isEqualTo("RUNNING");assertThat(count("stage_invocations")).isEqualTo(2);assertThatThrownBy(this::store).isInstanceOf(RuntimeException.class);assertThat(proxy.puts.get()).isEqualTo(2);
    }
    @Test void preexistingExactPairIsConfirmedWithoutAnyPut()throws Exception {prepare();fixture("seed","exact");var before=snapshot();store();assertThat(proxy.puts.get()).isZero();assertThat(inspectBronze().receiptConfirmed()).isTrue();assertThat(snapshot()).isEqualTo(before);assertThat(requests.get()).isEqualTo(1);}
    @ParameterizedTest @ValueSource(strings={"payload-only","metadata-only","bad-payload","bad-metadata","bad-type"}) void neverRepairsUnexpectedOrOrphanObjects(String state)throws Exception {prepare();fixture("seed",state);var before=snapshot();assertThatThrownBy(this::store).isInstanceOf(RuntimeException.class);noPrematureSuccess();assertThat(proxy.puts.get()).isZero();var inspection=inspectBronze();assertThat(inspection.receiptConfirmed()).isFalse();assertThat(inspection.state()).isEqualTo(state.equals("payload-only")?"PAYLOAD_ONLY":state.equals("metadata-only")?"METADATA_ONLY":"CONFLICT");assertThat(inspection.retryClassification()).isEqualTo(state.equals("payload-only"));assertThat(snapshot()).isEqualTo(before);assertThatThrownBy(this::store).isInstanceOf(RuntimeException.class);}
    @ParameterizedTest @ValueSource(strings={"before-put","between-puts","after-puts"}) void partialPublicationRemainsOccupiedAndInspectionNeverWrites(String fault)throws Exception {prepare();proxy.fault=fault;assertThatThrownBy(this::store).isInstanceOf(RuntimeException.class);noPrematureSuccess();proxy.fault="none";int writes=proxy.puts.get();var result=inspectBronze();assertThat(result.state()).isEqualTo(fault.equals("before-put")?"ABSENT":fault.equals("between-puts")?"PAYLOAD_ONLY":"EXACT");assertThat(result.receiptConfirmed()).isFalse();assertThat(result.retryClassification()).isEqualTo(!fault.equals("after-puts"));assertThat(proxy.puts.get()).isEqualTo(writes);assertThatThrownBy(this::store).isInstanceOf(RuntimeException.class);assertThat(requests.get()).isEqualTo(1);}
    @ParameterizedTest @ValueSource(strings={"generic-404","no-bucket","auth","io"}) void onlyExactNoSuchKeyProvesAbsence(String fault){prepare();proxy.fault=fault;assertThatThrownBy(this::store).hasMessage("BRONZE_UNAVAILABLE");noPrematureSuccess();assertThat(proxy.puts.get()).isZero();proxy.fault="none";assertThat(inspectBronze().state()).isEqualTo("ABSENT");}
    @Test void metadataPutAckLossUsesIndependentReadsWithoutAnotherPut(){prepare();proxy.fault="metadata-ack";store();proxy.fault="none";assertThat(proxy.puts.get()).isEqualTo(2);assertThat(inspectBronze().receiptConfirmed()).isTrue();assertThat(requests.get()).isEqualTo(1);}
    @ParameterizedTest @ValueSource(strings={"INTENT","BEFORE_AUTHORIZATION","AFTER_CHILD","VERIFIED","BEFORE_CHECKPOINT"}) void crashesNeverRelaunchAnIntent(String boundary){prepare();var latest=new AtomicReference<WorkerRepository.Owner>();assertThatThrownBy(()->store((point,o)->{latest.set(o);if(point.equals(boundary))throw new AssertionError("simulated crash");})).isInstanceOf(AssertionError.class);owner=latest.get();noPrematureSuccess();int writes=proxy.puts.get();workers=WorkerTestSupport.enabled(jdbc,tx,INSTALL);assertThatThrownBy(this::store).isInstanceOf(RuntimeException.class);assertThat(proxy.puts.get()).isEqualTo(writes);assertThat(inspectBronze().receiptConfirmed()).isFalse();}
    @ParameterizedTest @ValueSource(strings={"BEFORE_AUTHORIZATION","BEFORE_CHECKPOINT"}) void staleOwnerCannotWriteOrCommit(String boundary){prepare();assertThatThrownBy(()->store((point,o)->{if(point.equals(boundary))jdbc.update("UPDATE ddip_management.coordinator SET row_version=row_version+1");})).hasMessage("OWNERSHIP_LOST");noPrematureSuccess();assertThat(proxy.puts.get()).isEqualTo(boundary.equals("BEFORE_AUTHORIZATION")?0:2);}
    @Test void hostGuardLossVetoesLaunch(){prepare();assertThatThrownBy(()->store((point,o)->{if(point.equals("BEFORE_AUTHORIZATION"))guard.close();})).isInstanceOf(RuntimeException.class);assertThat(proxy.puts.get()).isZero();noPrematureSuccess();}
    @Test void changedJournalVetoesStorage()throws Exception {prepare();Files.write(journalDirectory.resolve("payload.xml"),new byte[]{1});assertThatThrownBy(this::store).isInstanceOf(RuntimeException.class);assertThat(proxy.puts.get()).isZero();assertThat(count("stage_invocations")).isEqualTo(1);}
    @Test void sourceRevisionChangeNeverReplacesTheCapturedFeed(){prepare();sources.execute(SourceCommands.command(SourceCommands.Action.REVISE,CONTENT,"demo-feed",SourceFixtures.revise("later",rss().put("feedEndpointId",ENDPOINT2)),"later","\"1\""),"test");var result=store();assertThat(SourceJson.parse(result.receipt()).get("revision").intValue()).isEqualTo(2);assertThat(requests.get()).isEqualTo(1);}
    @Test void credentialChangeAfterVerificationCannotCheckpoint()throws Exception {prepare();assertThatThrownBy(()->store((point,o)->{if(point.equals("BEFORE_CHECKPOINT"))try{Files.writeString(credentials,"{}");}catch(Exception ex){throw new IllegalStateException(ex);}})).isInstanceOf(RuntimeException.class);noPrematureSuccess();}
    @Test void missingD1CheckpointCannotPublish(){ready();assertThatThrownBy(this::store).isInstanceOf(RuntimeException.class);assertThat(proxy.puts.get()).isZero();assertThat(requests.get()).isZero();}
    @Test void lostReceiptAcknowledgmentIsReadOnlyAndDoesNotRefreshAuthority(){prepare();installLostCommit("SET state='BRONZE_VERIFIED'");loseAck.set(true);assertThatThrownBy(this::store).hasMessage("MANAGEMENT_UNAVAILABLE");assertThat(inspectBronze().receiptConfirmed()).isTrue();int writes=proxy.puts.get();assertThatThrownBy(this::store).hasMessage("OWNERSHIP_LOST");assertThat(proxy.puts.get()).isEqualTo(writes);}
    @ParameterizedTest @ValueSource(strings={"INSERT INTO ddip_management.stage_invocations","SET command_address="}) void lostIntentOrLaunchAckNeverStartsWriter(String statement){prepare();installLostCommit(statement);loseAck.set(true);assertThatThrownBy(this::store).hasMessage("MANAGEMENT_UNAVAILABLE");noPrematureSuccess();assertThat(proxy.puts.get()).isZero();assertThat(inspectBronze().state()).isEqualTo("ABSENT");assertThatThrownBy(this::store).hasMessage("OWNERSHIP_LOST");}
    @ParameterizedTest @ValueSource(strings={"rss_deliveries","stage_invocations","audit_events"}) void receiptStageAndAuditCommitAtomically(String table){prepare();assertThatThrownBy(()->store((point,o)->{if(point.equals("BEFORE_CHECKPOINT")){jdbc.execute("CREATE FUNCTION ddip_management.d2_fault() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION USING MESSAGE='PRIVATE',ERRCODE='23514'; END $$");jdbc.execute("CREATE TRIGGER d2_fault BEFORE "+(table.equals("audit_events")?"INSERT":"UPDATE")+" ON ddip_management."+table+" FOR EACH ROW EXECUTE FUNCTION ddip_management.d2_fault()");}})).hasMessage("STATE_CONFLICT");noPrematureSuccess();assertThat(inspectBronze().state()).isEqualTo("EXACT");assertThat(inspectBronze().receiptConfirmed()).isFalse();assertThat(proxy.puts.get()).isEqualTo(2);}
    @Test void modifiedReceiptCannotPassItsImmutableStageAnchor(){prepare();store();jdbc.update("UPDATE ddip_management.rss_deliveries SET receipt_bytes=?::bytea,row_version=row_version+1",SourceJson.canonical(SourceJson.object().put("unexpected",true)));assertThatThrownBy(this::inspectBronze).hasMessage("INPUT_CHANGED");assertThat(proxy.puts.get()).isEqualTo(2);assertThat(requests.get()).isEqualTo(1);}
    @Test void modifiedMetadataDigestCannotConfirmReceipt(){prepare();store();jdbc.update("UPDATE ddip_management.rss_deliveries SET metadata_sha256=?,row_version=row_version+1","0".repeat(64));assertThatThrownBy(this::inspectBronze).hasMessage("INPUT_CHANGED");assertThat(proxy.puts.get()).isEqualTo(2);assertThat(requests.get()).isEqualTo(1);}
    @Test void completedPairMutationCannotBeRepaired()throws Exception {prepare();store();fixture("seed","bad-payload");var bad=snapshot();assertThatThrownBy(this::inspectBronze).hasMessage("INPUT_CHANGED");assertThat(snapshot()).isEqualTo(bad);assertThat(proxy.puts.get()).isEqualTo(2);}
    @ParameterizedTest @ValueSource(strings={"storageBindingId","storageBindingSha256"}) void changedStorageProfileCannotLaunch(String field){prepare();var c=(tools.jackson.databind.node.ObjectNode)SourceJson.parse(jdbc.queryForObject("SELECT configuration_bytes FROM ddip_management.execution_profiles WHERE profile_id=?",byte[].class,bronzeRuntime));c.put(field,field.equals("storageBindingId")?BATCH:"0".repeat(64));byte[] raw=SourceJson.canonical(c);String changed="wrong-bronze-runtime";jdbc.update("INSERT INTO ddip_management.execution_profiles(profile_id,configuration_bytes,configuration_sha256) VALUES (?,?,?)",changed,raw,SourceJson.sha(raw));bronzeRuntime=changed;assertThatThrownBy(this::store).hasMessage("RUNTIME_MISMATCH");assertThat(proxy.puts.get()).isZero();assertThat(count("stage_invocations")).isEqualTo(1);bronzeRuntime="bronze-test";}
    @Test void staleEpochCannotCreateStorageIntent(){prepare();var w=owner.worker();var stale=new WorkerRepository.Session(w.installationId(),w.instanceId(),w.profileId(),w.profileDigest(),w.deploymentDigest(),w.hostDigest(),w.status(),w.epoch()-1,w.coordinatorVersion(),w.workerVersion());owner=new WorkerRepository.Owner(stale,owner.runId(),owner.attemptId(),owner.runVersion(),owner.attemptVersion(),owner.attemptState());assertThatThrownBy(this::store).hasMessage("OWNERSHIP_LOST");assertThat(proxy.puts.get()).isZero();assertThat(count("stage_invocations")).isEqualTo(1);}
    @Test void competingStorageInvocationsHaveOneWinner()throws Exception {prepare();var barrier=new java.util.concurrent.CyclicBarrier(2);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var outcomes=new ArrayList<java.util.concurrent.Future<String>>();for(int i=0;i<2;i++)outcomes.add(pool.submit(()->{barrier.await(5,java.util.concurrent.TimeUnit.SECONDS);try{RssBronzeTestSupport.store(jdbc,tx,WorkerTestSupport.enabled(jdbc,tx,INSTALL),guard,owner,bronzeRuntime,(p,o)->{});return "VERIFIED";}catch(WorkerFailure ex){return ex.code().name();}}));assertThat(List.of(outcomes.get(0).get(20,java.util.concurrent.TimeUnit.SECONDS),outcomes.get(1).get(20,java.util.concurrent.TimeUnit.SECONDS))).containsExactlyInAnyOrder("VERIFIED","OWNERSHIP_LOST");}assertThat(proxy.puts.get()).isEqualTo(2);assertThat(count("stage_invocations")).isEqualTo(2);assertThat(inspectBronze().receiptConfirmed()).isTrue();}
    @ParameterizedTest @ValueSource(strings={"BEFORE_AUTHORIZATION","BEFORE_CHECKPOINT"}) void dbOutageNeverReleasesOrRepeatsWrites(String boundary){prepare();assertThatThrownBy(()->store((point,o)->{if(point.equals(boundary))outage(true);})).hasMessage("MANAGEMENT_UNAVAILABLE");outage(false);noPrematureSuccess();int writes=proxy.puts.get();assertThat(inspectBronze().receiptConfirmed()).isFalse();assertThatThrownBy(this::store).hasMessage("OWNERSHIP_LOST");assertThat(proxy.puts.get()).isEqualTo(writes);}
    @Test void checkpointSurvivesActualDatabaseRestart()throws Exception {prepare();var stored=store();owner=stored.owner();var original=snapshot();var receipt=jdbc.queryForObject("SELECT receipt_bytes FROM ddip_management.rss_deliveries",byte[].class);String signal=System.getProperty("ddip.test.bronze-restart-signal");if(signal!=null){Path p=Path.of(signal);Files.writeString(p,"RESTART\n");long end=System.nanoTime()+java.time.Duration.ofSeconds(60).toNanos();while(!Files.exists(Path.of(signal+".done")) && System.nanoTime()<end)Thread.sleep(50);assertThat(Files.exists(Path.of(signal+".done"))).isTrue();}assertThat(inspectBronze().receiptConfirmed()).isTrue();assertThat(jdbc.queryForObject("SELECT receipt_bytes FROM ddip_management.rss_deliveries",byte[].class)).isEqualTo(receipt);assertThat(snapshot()).isEqualTo(original);assertThat(proxy.puts.get()).isEqualTo(2);assertThat(requests.get()).isEqualTo(1);}
}
